// Package api is the maild RPC contract: JSON-RPC 2.0 over a Unix socket,
// specified in docs/specs/rpc-protocol.md. zz_generated.go is generated by
// tools/rpcgen from schema/rpc; this file and its siblings name the runtime
// it relies on, which lodge's kit provides
// (github.com/frostyard/lodge/kit/jsonrpc). Edit the schema, never the
// generated file.
package api

import (
	"context"
	"encoding/json/jsontext"
	"slices"

	"github.com/frostyard/lodge/kit/jsonrpc"
)

// ErrorCode is a JSON-RPC error code; the generated constants name them.
type ErrorCode int

// Error is a JSON-RPC error object. Handlers return one to choose the code;
// any other error reaches the client as CodeInternal.
type Error = jsonrpc.Error[ErrorCode]

// Errorf returns an *Error with a formatted message.
func Errorf(code ErrorCode, format string, args ...any) *Error {
	return jsonrpc.Errorf(code, format, args...)
}

// Event is a generated event type, and EventEnvelope the params of an
// "event" notification.
type (
	Event         = jsonrpc.Event
	EventEnvelope = jsonrpc.EventEnvelope
)

// NewEnvelope encodes ev for delivery.
func NewEnvelope(seq int64, ev Event) (EventEnvelope, error) { return jsonrpc.NewEnvelope(seq, ev) }

type handlerFunc = jsonrpc.HandlerFunc

// Router maps wire method names to service implementations. Unknown
// methods, methods the request's caller (CallerFrom) may not use, and for
// an agent methods its scope does not grant (MethodNeed), return
// ErrMethodNotFound alike.
type Router struct {
	*jsonrpc.Router[CallerKind, ErrorCode]
}

// NewRouter registers every service; a nil service is an error.
func NewRouter(s Services) (*Router, error) {
	r := &Router{jsonrpc.NewRouter[CallerKind, ErrorCode](jsonrpc.RouterOptions[CallerKind]{
		Caller: func(ctx context.Context) CallerKind { return CallerFrom(ctx).Kind },
		Admit: func(ctx context.Context, method string, _ jsonrpc.Route[CallerKind]) bool {
			c := CallerFrom(ctx)
			return c.Kind != CallerKindAgent || c.Scope.Grants(MethodNeed(method))
		},
	})}
	if err := s.register(r); err != nil {
		return nil, err
	}
	return r, nil
}

func (r *Router) handle(method string, h handlerFunc) {
	r.Handle(method, jsonrpc.Route[CallerKind]{Callers: methodCallers[method], Writes: MethodNeed(method) != NeedRead, Handler: h})
}

func decodeParams(raw jsontext.Value, p any, required []string) error {
	return jsonrpc.DecodeParams[ErrorCode](raw, p, required)
}

// HasMethod reports whether the schema defines method.
func HasMethod(method string) bool { return slices.Contains(Methods, method) }
